import type {JournalArticleData} from '@/components/LocalizedRich';
export const journalEs:Record<string,JournalArticleData>={
"regata-storica-2026":{slug:"regata-storica-2026",eventDate:"6 DE SEPTIEMBRE DE 2026",title:"Regata Storica de Venecia 2026",category:"Eventos",description:"Desfile histórico sobre el agua, voga alla veneta y regatas en el Gran Canal el domingo 6 de septiembre de 2026.",lead:"El domingo 6 de septiembre de 2026 Venecia celebra una de sus citas más espectaculares y queridas: la Regata Storica. Cada primer domingo de septiembre, el Gran Canal se convierte en escenario de historia, voga alla veneta, embarcaciones tradicionales y competición.",image:"/images/journal-regata-storica-2026.webp",imageAlt:"Embarcaciones históricas durante la Regata Storica en el Gran Canal de Venecia",sections:[["El desfile histórico sobre el agua","A las 15:30 comienza el Corteo Storico-Sportivo: embarcaciones históricas con figurantes vestidos de época, góndolas y barcos de las asociaciones de voga alla veneta recorren la cuenca de San Marcos, el Gran Canal, Rialto y la estación, para regresar después hasta Ca’ Foscari. El cortejo histórico recuerda la bienvenida ofrecida a Caterina Cornaro en 1489."],["Las regatas en el Gran Canal","Desde las 16:00 empiezan las carreras. Entre las más esperadas están las caorline de seis remos a las 17:10, la regata femenina en mascarete de dos remos a las 17:40 y los gondolini de dos remos a las 18:10. El programa incluye también el desafío internacional universitario en galeoni de ocho remos."],["Dónde ver la Regata Storica","La cuenca de San Marcos y Punta della Dogana, Rialto, la zona de San Marcuola y Ca’ Foscari son algunos de los puntos más interesantes. Las orillas del Gran Canal se llenan muy pronto: si quieres encontrar un buen lugar, llega con bastante antelación."],["Atención al transporte","El 6 de septiembre el servicio de navegación ACTV sufrirá cambios o interrupciones durante la tarde. La información oficial indica modificaciones aproximadamente entre las 14:00 y las 19:30, con suspensión en el Gran Canal alrededor de las 15:00-19:30. Desde Marghera recomendamos llegar en autobús o tren y contar con más desplazamientos a pie."],["Por qué merece la pena verla","La Regata Storica no es simplemente un espectáculo pensado para turistas. La voga alla veneta sigue siendo una tradición viva y esta jornada es uno de los momentos más importantes del calendario de remo veneciano. Historia, deporte y pasión local comparten el mismo canal."],["Información práctica","Fecha: domingo 6 de septiembre de 2026. Lugar: Gran Canal, Venecia. Cortejo histórico hacia las 15:30 y regatas desde las 16:00. El programa y el transporte pueden cambiar: comprueba siempre la web oficial poco antes de la visita."]],tip:"Llega pronto a Venecia en autobús o tren, decide con antelación en qué zona del Gran Canal quieres verla y organiza el regreso antes de que termine el programa.",official:["Web oficial de la Regata Storica","https://www.regatastoricavenezia.it/en/"]},
"vogalonga-2027":{slug:"vogalonga-2027",title:"Vogalonga en Venecia: la gran fiesta del remo en la laguna",category:"Eventos",eventDate:"MAYO DE 2027",description:"30 kilómetros no competitivos por la laguna, las islas y el Gran Canal: la Vogalonga celebra Venecia, el remo y una relación más respetuosa con el agua.",lead:"La Vogalonga es una de esas citas que permiten ver Venecia desde una perspectiva diferente. Miles de remeros y embarcaciones llegados de numerosos países se reúnen en la laguna para completar un largo recorrido no competitivo dedicado a la ciudad, sus islas y la tradición del remo.",image:"/images/journal-vogalonga-2027-cover.webp",cardImage:"/images/journal-vogalonga-2027-card.webp",imageAlt:"Numerosas embarcaciones de remo durante la Vogalonga en la laguna de Venecia",sections:[["¿Qué es la Vogalonga?","La Vogalonga es una manifestación de remo no competitiva que se presenta como un acto de amor por Venecia, su laguna, sus islas y sus embarcaciones. Mantiene además un objetivo de respeto consciente por la naturaleza y la cultura de la ciudad."],["30 kilómetros entre laguna, islas y Gran Canal","El recorrido histórico tiene unos 30 kilómetros y atraviesa la laguna veneciana, pasa junto a varias islas y termina entrando en el Gran Canal. La combinación de paisaje, agua y ciudad la convierte también en un espectáculo magnífico para quienes observan desde tierra."],["Miles de remeros y embarcaciones","La web oficial habla de alrededor de 8.000 remeros y unas 2.000 embarcaciones. Pueden participar barcos a remo de distintos tamaños y con diferente número de tripulantes: no gana quien llega primero, porque el espíritu es participar."],["Por qué la Vogalonga representa a Venecia","La manifestación homenajea las antiguas técnicas de navegación y promueve embarcaciones sostenibles. También recuerda la necesidad de proteger Venecia del oleaje generado por el tráfico motorizado."],["Dónde verla","Quien no participa puede disfrutar del ambiente desde distintos puntos del recorrido. La entrada de la gran flotilla en el Gran Canal es uno de los momentos más impresionantes. Conviene revisar las comunicaciones oficiales por posibles cambios en la navegación y el transporte público."],["Edición 2027","La próxima edición está prevista para mayo de 2027; la fecha exacta deberá confirmarse en la web oficial. Allí se publicarán las inscripciones, el recorrido definitivo y cualquier información organizativa o de transporte."]],tip:"Llega temprano a Venecia y evita llenar el día de horarios. Elige una zona desde la que seguir la Vogalonga y deja tiempo para pasear por barrios menos concurridos.",official:["Vogalonga – web oficial","https://vogalonga.com/en/"]},
'carnevale-di-venezia':{slug:'carnevale-di-venezia',eventDate:"23 DE ENERO – 9 DE FEBRERO DE 2027",title:'Carnaval de Venecia 2027',category:'Eventos',description:'Del 23 de enero al 9 de febrero de 2027, máscaras, espectáculos y tradiciones transforman Venecia en un gran escenario al aire libre.',lead:'El Carnaval es uno de los momentos más especiales del año. Lo mejor es combinar los grandes eventos con paseos por zonas menos concurridas.',image:'/images/journal-carnevale.webp',imageAlt:'Ambiente del Carnaval de Venecia',sections:[['Elegir el momento','San Marcos concentra muchos actos, pero el ambiente se extiende por toda la ciudad. Llegar temprano suele ser una buena idea.'],['Máscaras y disfraces','Los trajes históricos forman parte de la identidad del Carnaval. Fotografía con respeto y no bloquees pasos estrechos.'],['Desde Marghera','Deja el coche en el aparcamiento privado y utiliza transporte público. Si te quedas hasta tarde, revisa las conexiones nocturnas.']],tip:'Consulta siempre el programa oficial: fechas, accesos y eventos cambian cada edición.',official:['Programa oficial del Carnaval','https://carnevale.venezia.it/en/']},
'festa-del-redentore':{slug:'festa-del-redentore',eventDate:"17 DE JULIO DE 2027",title:'Festa del Redentore 2027',category:'Eventos',description:'El sábado 17 de julio de 2027, una de las grandes fiestas de verano de Venecia alcanza su momento más esperado entre barcos, tradición y fuegos artificiales.',lead:'El Redentore combina tradición religiosa y celebración popular. La noche del sábado, la laguna se convierte en el centro de la fiesta.',image:'/images/journal-redentore.webp',imageAlt:'Barcos en la laguna durante el Redentore',sections:[['Una fiesta muy veneciana','Más allá de los fuegos, es una noche de convivencia en barcos, orillas y barrios de la ciudad.'],['Planificar con tiempo','Puede haber cambios de circulación y transporte. Deja margen extra y consulta las comunicaciones oficiales.'],['Volver a Marghera','Las conexiones nocturnas son especialmente útiles después del espectáculo. Organiza el regreso antes de entrar en las zonas más concurridas.']],tip:'No elijas el punto de observación en el último momento: las zonas más populares se llenan pronto.',official:['Ayuntamiento de Venecia – información oficial','https://www.comune.venezia.it/en']},
'natale-capodanno-venezia':{slug:'natale-capodanno-venezia',title:'Navidad y Nochevieja en Venecia',category:'Temporada',description:'Luces de invierno, ambiente festivo y celebraciones de fin de año en la laguna.',lead:'Venecia en invierno tiene una atmósfera muy distinta al verano: luz suave, días cortos y, a veces, calles más tranquilas.',image:'/images/journal-natale-capodanno.webp',imageAlt:'Venecia iluminada durante las fiestas',sections:[['Venecia en invierno','Lleva ropa de abrigo y calzado adecuado: la humedad y el viento pueden aumentar la sensación de frío.'],['Navidad','Decoraciones, mercados y eventos cambian cada año. Los museos son una excelente alternativa en días de mal tiempo.'],['Nochevieja','Revisa los eventos oficiales, posibles restricciones y horarios de transporte antes de salir.']],tip:'Reserva restaurantes y actividades importantes con antelación en las fechas festivas.',official:['Venezia Unica – información oficial','https://www.veneziaunica.it/en']},
'mostra-del-cinema':{slug:'mostra-del-cinema',eventDate:"2–12 DE SEPTIEMBRE DE 2026",title:'Festival de Cine de Venecia 2026',category:'Arte y cultura',description:'La 83.ª Mostra de Venecia se celebra del 2 al 12 de septiembre de 2026 en el Lido, con estrenos, proyecciones para el público, alfombra roja y Venice Immersive.',lead:'Del 2 al 12 de septiembre de 2026, el Lido de Venecia vuelve a convertirse en uno de los grandes centros del cine internacional. La 83.ª Mostra Internazionale d’Arte Cinematografica está organizada por La Biennale di Venezia y dirigida por Alberto Barbera.',image:'/images/journal-mostra-cinema.webp',imageAlt:'Festival de Cine de Venecia en el Lido',sections:[['La edición de 2026','Durante once días, el centro del festival se concentra alrededor del Palazzo del Cinema, el Palazzo del Casinò, la Sala Darsena y otros espacios de La Biennale en el Lido.'],['Ver cine sin acreditación','La Mostra no está reservada únicamente a profesionales e invitados. Muchas proyecciones tienen entrada para el público con compra online, mientras que algunas grandes premieres son solo con invitación. Conviene revisar siempre el programa oficial del día.'],['Venice Immersive','En la Isola del Lazzaretto Vecchio, frente a Riva di Corinto, Venice Immersive reúne 68 proyectos XR de 26 países: realidad virtual y mixta, mundos virtuales e instalaciones inmersivas.'],['Alfombra roja y momentos especiales','El 2 de septiembre George Clooney recibirá el León de Oro a la trayectoria durante la ceremonia de apertura. Los invitados y horarios de la alfombra roja cambian cada día, así que es mejor consultar el calendario oficial antes de ir.'],['Cómo llegar al Lido desde Marghera','La opción más sencilla es llegar a Venecia en autobús o tren y continuar en vaporetto hasta el Lido. En los días más importantes del festival conviene reservar más tiempo para transbordos y colas.'],['Un domingo especialmente intenso','El domingo 6 de septiembre también se celebra la Regata Storica en el Gran Canal. Si quieres vivir ambos eventos, organiza bien los desplazamientos y ten en cuenta posibles cambios en la navegación.']],tip:'Para vivir el ambiente sin convertir el día en una carrera, elige una proyección abierta al público, deja tiempo para pasear por el Lido y revisa el programa y los transportes el mismo día.',official:['La Biennale – Cinema 2026','https://www.labiennale.org/en/cinema/2026']},
'homo-faber-2026':{slug:'homo-faber-2026',eventDate:"1–30 DE SEPTIEMBRE DE 2026",title:'Homo Faber 2026: An Island of Light',category:'Arte y cultura',description:'Del 1 al 30 de septiembre, Homo Faber convierte la Fondazione Giorgio Cini, en San Giorgio Maggiore, en un escaparate internacional de la artesanía contemporánea.',lead:'Homo Faber 2026: An Island of Light propone durante un mes un viaje por la relación entre la luz, los materiales y la mano humana. La cuarta edición está dirigida artísticamente por Es Devlin y se celebra en la Fondazione Giorgio Cini, en la isla de San Giorgio Maggiore.',image:'/images/journal-homo-faber-2026-cover.webp',cardImage:'/images/journal-homo-faber-2026-card.webp',imageAlt:'Imagen oficial de Homo Faber 2026 An Island of Light',posterHero:true,sections:[['¿Qué es Homo Faber?','Homo Faber es una bienal internacional dedicada a la excelencia de la artesanía contemporánea. La edición de 2026 reúne cientos de objetos hechos a mano por artesanos y creadores de todo el mundo.'],['An Island of Light','Bajo la dirección artística de Es Devlin, la edición explora el vínculo entre luz, materia y gesto artesanal. Quince instalaciones inmersivas ocupan los espacios históricos y jardines de la Fondazione Giorgio Cini.'],['Mucho más que una exposición','El programa incluye demostraciones en vivo, talleres participativos, experiencias gastronómicas y visitas especiales. Es una oportunidad para descubrir no solo los objetos terminados, sino también los conocimientos y procesos que hay detrás.'],['San Giorgio Maggiore, un lugar especial','La isla está a pocos minutos en vaporetto de la plaza de San Marcos, pero ofrece un ambiente mucho más tranquilo. La visita se puede combinar con la basílica de San Giorgio Maggiore y las vistas sobre el Bacino di San Marco.'],['Homo Faber in Città','El proyecto también se extiende por Venecia con exposiciones e iniciativas que conectan artesanía, diseño, materiales y maestros locales durante todo el mes de septiembre.'],['Información práctica','Homo Faber 2026 se celebra del 1 al 30 de septiembre en la Fondazione Giorgio Cini. Horarios, entradas, talleres y programa diario pueden variar: consulta la web oficial antes de la visita.']],tip:'Reserva al menos medio día para San Giorgio. Si te interesan el arte, el diseño y los procesos artesanales, revisa también el programa diario para encontrar demostraciones y talleres.',official:['Homo Faber 2026 – web oficial','https://www.homofaber.com/en/biennial/homofaber-2026']},
'biennale-di-venezia':{slug:'biennale-di-venezia',eventDate:"9 DE MAYO – 22 DE NOVIEMBRE DE 2026",title:'Biennale Arte de Venecia 2026',category:'Arte y cultura',description:'La 61.ª Exposición Internacional de Arte In Minor Keys se celebra del 9 de mayo al 22 de noviembre de 2026 entre Giardini, Arsenale, Forte Marghera y otros espacios de Venecia.',lead:'La Biennale es una buena ocasión para conocer zonas de Venecia que suelen quedar fuera de una primera visita.',image:'/images/journal-biennale.webp',imageAlt:'Exposición de la Bienal de Venecia',sections:[['Giardini','Los pabellones nacionales ocupan los jardines históricos de Castello y requieren varias horas.'],['Arsenale','Los enormes espacios del Arsenale albergan una parte importante de la exposición internacional.'],['Exposiciones por la ciudad','Palacios y espacios temporales amplían el programa por distintos barrios.']],tip:'No intentes verlo todo en un día: elige una zona principal y deja tiempo para caminar.',official:['La Biennale – web oficial','https://www.labiennale.org/en/art/2026']},
'venezia-con-bambini':{slug:'venezia-con-bambini',title:'Venecia con niños',category:'Familias',description:'Museos, vaporetto, plazas y pausas bien colocadas para disfrutar en familia.',lead:'Con niños, Venecia funciona mejor como una aventura que como una lista de monumentos que tachar.',image:'/images/venezia-bambini-campo-nuova.webp',imageAlt:'Niños en un campo veneciano',sections:[['Reducir distancias','Puentes y escaleras cansan rápido. Alterna caminatas, vaporetto y descansos.'],['Convertir el paseo en juego','Buscar leones alados, contar puentes u observar barcos puede mantener su atención.'],['Pocos objetivos','Un museo, una plaza y un trayecto en vaporetto pueden ser suficientes para un gran día.']],tip:'Añade siempre una pausa extra: con niños, un plan flexible suele funcionar mejor.',official:['MUVE – Museos de Venecia','https://msn.visitmuve.it/en/home/']},
'venezia-con-il-cane':{slug:'venezia-con-il-cane',title:'Venecia con perro',category:'Mascotas',description:'Consejos prácticos para explorar Venecia con tu compañero de cuatro patas.',lead:'Venecia se puede visitar con perro, pero conviene pensar en puentes, calor, multitudes y normas de transporte.',image:'/images/journal-venezia-cane.webp',imageAlt:'Visitar Venecia con un perro',sections:[['Elegir horarios','En verano, mejor primera hora y final de la tarde para evitar suelo caliente y demasiada gente.'],['Transporte','Lleva correa y bozal disponibles y revisa siempre las normas ACTV actualizadas.'],['Agua y descansos','Lleva un cuenco plegable y para con frecuencia en zonas tranquilas.']],tip:'Castello, Sant’Elena y algunas zonas del Lido suelen ser más agradables para pasear con perro.',official:['AVM/ACTV – transporte en Venecia','https://avm.avmspa.it/en/content/venice-urban-services-0']},
'acqua-alta-a-venezia':{slug:'acqua-alta-a-venezia',title:'Acqua alta en Venecia',category:'Venecia práctica',description:'Qué es la marea alta y cómo adaptar la visita sin dramatizar.',lead:'El acqua alta es un fenómeno de marea: no inunda toda la ciudad por igual ni durante todo el día.',image:'/images/journal-acqua-alta.webp',imageAlt:'Marea alta en una zona peatonal de Venecia',sections:[['Qué ocurre','Las zonas más bajas se ven afectadas primero. El nivel depende de marea, viento y condiciones meteorológicas.'],['Mirar las previsiones','Consulta información oficial y adapta la ruta si es necesario.'],['El sistema MOSE','MOSE protege la laguna en episodios importantes, pero las condiciones del día deben comprobarse igualmente.']],tip:'Calzado adecuado y una ruta flexible suelen ser suficientes en episodios moderados.',official:['Ayuntamiento de Venecia – previsión de mareas','https://www.comune.venezia.it/en/content/tide-forecasting-and-reporting-centre']},
'dove-parcheggiare-venezia':{slug:'dove-parcheggiare-venezia',title:'Dónde aparcar para visitar Venecia',category:'Transporte',description:'Aparcamiento del apartamento, Piazzale Roma o Tronchetto: las principales opciones al llegar en coche.',lead:'El centro histórico de Venecia no es accesible en coche, por lo que el vehículo debe quedarse antes de la zona peatonal.',image:'/images/journal-parcheggi-venezia.webp',imageAlt:'Acceso por carretera y aparcamientos antes de Venecia',sections:[['La opción más sencilla','Nuestros huéspedes tienen aparcamiento privado gratuito en Marghera y pueden ir a Venecia en bus o tren.'],['Piazzale Roma','Es el punto de acceso por carretera más cercano al centro, con garajes de pago.'],['Tronchetto','Otra gran zona de aparcamiento conectada con Venecia mediante transporte público.']],tip:'Para la mayoría de nuestros huéspedes, dejar el coche en el apartamento es más económico y relajado.',official:['AVM – Autorimessa Comunale','https://avm.avmspa.it/it/content/autorimessa-comunale-1']},
'spritz-veneziano':{slug:'spritz-veneziano',title:'El Spritz veneciano',category:'Sabores y tradiciones',description:'Un símbolo del aperitivo veneciano que conviene disfrutar con moderación.',lead:'En Venecia, el Spritz forma parte de un ritual social: parar en un bacaro, hablar y acompañarlo con algunos cicchetti.',image:'/images/journal-spritz.webp',imageAlt:'Spritz servido durante el aperitivo',sections:[['Más que un cóctel','El Spritz pertenece a la cultura del aperitivo y cambia según el bitter utilizado.'],['En un bacaro','Los locales de barrio suelen ofrecer una experiencia más natural que las zonas más turísticas.'],['Consumo responsable','Si conduces, evita el alcohol o utiliza transporte público para regresar.']],tip:'Prueba un Spritz con algunos cicchetti y disfruta del ambiente sin prisas.',official:['Aperol – web oficial','https://terrazza.aperol.com/en/']},
'cicchetti-veneziani':{slug:'cicchetti-veneziani',title:'Cicchetti venecianos',category:'Sabores y tradiciones',description:'Pequeños bocados, bacari y una forma muy veneciana de comer por etapas.',lead:'Los cicchetti son pequeñas porciones servidas en bacari. Una de las mejores formas de probarlos es visitar varios locales y pedir poco en cada uno.',image:'/images/journal-cicchetti.webp',imageAlt:'Selección de cicchetti venecianos',sections:[['Qué son','Pescado, verduras, carne o crostini: la selección cambia según el local y la hora.'],['Hacer varias paradas','Dos o tres bacari en el mismo barrio permiten comparar especialidades y ambientes.'],['Respetar el espacio','No bloquees entradas ni calles estrechas y deposita correctamente los residuos.']],tip:'Pide pocos cicchetti en cada parada: la gracia está en cambiar de sabores y de lugares.'},
'buone-maniere-a-venezia':{slug:'buone-maniere-a-venezia',title:'Disfrutar Venecia con respeto',category:'Vivir Venecia',description:'Pequeñas normas de sentido común para respetar una ciudad única y habitada.',lead:'Venecia no es un decorado: hay personas que viven, trabajan y se desplazan cada día por espacios muy estrechos.',image:'/images/journal-buone-maniere.webp',imageAlt:'Visitantes caminando por Venecia',sections:[['No bloquear el paso','Puentes, calles estrechas y entradas deben quedar libres. Para mirar el mapa, busca un espacio más amplio.'],['Respetar el agua y la ciudad','No te bañes en los canales y no dejes residuos.'],['Cuidar el volumen','En zonas residenciales, sobre todo de noche, evita gritos y ruido innecesario.']],tip:'La mejor forma de querer Venecia es visitarla como una ciudad real, no como un parque temático.',official:['Ayuntamiento de Venecia – web oficial','https://www.comune.venezia.it/en']},
};
